            "type": "paragraph",
            "content": "আজই আগের পরীক্ষার পাঁচটি ঘটনা লিখে প্রতিটির পাশে “এবার কী করব” rule দাও। তারপর একটি ৭ দিনের review date ঠিক করো। সপ্তাহে একবার সেই rules timed mock-এ পরীক্ষা করো লিখে রাখো এবং next review-তে feeling নয়, evidence দিয়ে পরিবর্তন করো। যদি task অসম্পূর্ণ থাকে, শাস্তি হিসেবে double hours দিও না; কারণ লিখে next available block-এ পুনঃস্থাপন করো।"
