            "content": "তাসনিয়া যখন আবার পড়ার টেবিলে বসল, তার সামনে শুধু বই ছিল না; ছিল আগের result, আত্মীয়ের প্রশ্ন, বন্ধুদের progress এবং নিজের মাথায় জমে থাকা “যদি”। Second timer-এর কাজ সেই শব্দগুলোকে অস্বীকার করা নয়। কাজ হলো কোন শব্দ data, কোনটি pressure, আর কোনটি শুধু noise—তা আলাদা করা। তাসনিয়া একটি matrix বানিয়ে high-frequency কিন্তু medium-weak topics আগে নেয়। low-frequency hard topics শেষে রাখে। এই chapter-এর ফোকাস হলো সব topic সমান নয়; exam frequency, marks, weakness ও improvement cost একসঙ্গে দেখলে priority বাস্তব হয়।।"
