      {
        "title": "Hook",
        "blocks": [
          {
            "type": "paragraph",
            "content": "তাহমিদ যখন আবার পড়ার টেবিলে বসল, তার সামনে শুধু বই ছিল না; ছিল আগের result, আত্মীয়ের প্রশ্ন, বন্ধুদের progress এবং নিজের মাথায় জমে থাকা “যদি”। Second timer-এর কাজ সেই শব্দগুলোকে অস্বীকার করা নয়। কাজ হলো কোন শব্দ data, কোনটি pressure, আর কোনটি শুধু noise—তা আলাদা করা। দিয়া ঘুম কম হওয়ায় full chapter করতে পারেনি। সে ২০ মিনিট recall, ১৫টি প্রশ্ন ও error review করে day close করে। এই chapter-এর ফোকাস হলো খারাপ দিন পুরো plan বাতিল করার কারণ নয়; minimum viable action থাকলে momentum রক্ষা হয়।।"
          }
        ],
        "id": "section-044-01"
      },
      {
        "title": "Problem",
        "blocks": [
          {
            "type": "paragraph",
            "content": "দ্বিতীয়বার প্রস্তুতিতে সবচেয়ে বিপজ্জনক ভুল হলো পুরোনো preparation-কে নতুন করে সাজানোর বদলে পুরোনো routine-কে পুনরাবৃত্তি করা। মানুষ সাধারণত যেখানে স্বচ্ছন্দ, সেখানে ফিরে যায়: পছন্দের subject, পরিচিত বই, passive reading, সুন্দর timetable বা endless planning। কিন্তু পরীক্ষার score আটকে থাকে অন্য জায়গায়—recall, accuracy, time choice, weak topic এবং error correction-এ। খারাপ দিনে লক্ষ্য perfect day নয়; chain না ভাঙা।"
          }
        ],
        "id": "section-044-02"
      },
      {
        "title": "Reality",
        "blocks": [
          {
            "type": "paragraph",
            "content": "recovery protocol all-or-nothing thinking ভাঙে তাই আজকের প্রশ্ন “আমি কত ঘণ্টা বসেছি?” নয়; বরং “আমি কী প্রমাণ তৈরি করেছি?” একটি topic পড়া হয়েছে—তার প্রমাণ কী? একটি question set করা হয়েছে—তার ভুলের কারণ কী? একটি mock দেওয়া হয়েছে—পরের test-এ কোন rule বদলাবে? এই প্রশ্নগুলো preparation-কে emotion থেকে measurement-এ নিয়ে যায়।"
          }
        ],
        "id": "section-044-03"
      },
      {
        "title": "Mentor Explanation",
        "blocks": [
          {
            "type": "paragraph",
            "content": "প্রথমে previous score, attempt, correct/wrong answer, time loss ও repeated mistake এক জায়গায় রাখো। score কম হলে knowledge, retrieval এবং decision gap আলাদা করো; প্রতিটির corrective action আলাদা। remaining days, target unit ও high-yield topic দেখে A, B এবং C priority তৈরি করো—usable mastery, reliable coverage ও selective exposure হিসেবে।"
          },
          {
            "type": "paragraph",
            "content": "তৃতীয় ধাপ হলো feedback loop। প্রশ্ন করার পরে ভুলকে সঙ্গে সঙ্গে answer key দিয়ে ঢেকে দিও না। আগে বলো তুমি কী ভেবেছিলে, কোন clue মিস হয়েছে, কোন option কেন attractive লেগেছে, এবং একই trigger আবার এলে কী করবে। এই explanation-ই তোমার Error Log-এর মূল উপাদান। ভুলের পাশে revision date না থাকলে log archive হয়ে যায়; revision date থাকলে সেটি training schedule হয়।"
          }
        ],
        "id": "section-044-04"
      },
      {
        "title": "Strategy",
        "blocks": [
          {
            "type": "paragraph",
            "content": "প্রথমে একটি নির্দিষ্ট block বেছে নাও এবং তার output লিখো। “গণিত পড়ব” output নয়; “quadratic equation-এর ২০টি mixed question-এ অন্তত ১৬টি correct এবং সব ভুলের কারণ লিখব”—এটি output।"
          },
          {
            "type": "paragraph",
            "content": "block-এর শুরুতে বই বন্ধ করে আগের session-এর পাঁচটি prompt recall করো। ভুল হলে সেটি failure নয়; আজকের warm-up diagnosis।"
          },
          {
            "type": "paragraph",
            "content": "timed practice-এর পরে তিন রঙে চিহ্নিত করো: সবুজ—নিজে সঠিক; হলুদ—সঠিক হলেও ধীর বা অনিশ্চিত; লাল—ভুল বা blank। পরের revision-এর priority রঙ দিয়ে ঠিক করো।"
          },
          {
            "type": "paragraph",
            "content": "দিনের শেষে metric লিখো: effective minutes, question accuracy, unresolved errors এবং আগামী দিনের first task। এই চারটি সংখ্যা preparation-এর চেহারা দেখায়।"
          }
        ],
        "id": "section-044-05"
      },
      {
        "title": "Example",
        "blocks": [
          {
            "type": "paragraph",
            "content": "তাহমিদ-এর মতো একজন candidate যদি প্রতিদিন ৬ ঘণ্টা পায়, সে দুইটি ৮০-মিনিট deep block, একটি ৬০-মিনিট timed set, একটি ৪০-মিনিট error review এবং ছোট recall block রাখতে পারে। কোনো দিন energy কমলে full plan-এর বদলে minimum version হবে: ২০ মিনিট recall, ১৫টি প্রশ্ন এবং ১০ মিনিট correction। এতে system ভাঙে না, আবার sleep বা health-এর বিরুদ্ধে যুদ্ধও হয় না।"
          }
        ],
        "id": "section-044-06"
      },
      {
        "title": "Action Plan",
        "blocks": [
          {
            "type": "paragraph",
            "content": "আজই red, yellow, green energy অনুযায়ী task menu বানাও। তারপর একটি ৭ দিনের review date ঠিক করো। mobile দূরে রেখে পাঁচ মিনিট start rule নাও লিখে রাখো এবং next review-তে feeling নয়, evidence দিয়ে পরিবর্তন করো। যদি task অসম্পূর্ণ থাকে, শাস্তি হিসেবে double hours দিও না; কারণ লিখে next available block-এ পুনঃস্থাপন করো।"
          }
        ],
        "id": "section-044-07"
      },
      {
        "title": "Checklist",
        "blocks": [
          {
            "type": "paragraph",
            "content": "- আমি কি topic বা goal-কে measurable output-এ লিখেছি?\n- আমি কি recall, practice, revision এবং correction—চারটি আলাদা কাজ রেখেছি?\n- আমার আজকের priority কি অন্যের routine নয়, নিজের data থেকে এসেছে?\n- ভুল হলে কি trigger এবং prevention rule লিখেছি?\n- আগামী block-এর প্রথম task কি পরিষ্কার?"
          }
        ],
        "id": "section-044-08"
      },
      {
        "title": "Chapter Note",
        "blocks": [
          {
            "type": "paragraph",
            "content": "এই chapter শেষ করার পর একটি বাক্যে লিখো: “আমার বর্তমান preparation-এর সবচেয়ে বড় controllable gap হলো ______।” ফাঁকা ঘরটি সত্যি করে পূরণ করাই দ্বিতীয়বারের নতুন শুরু।"
          }
        ],
        "id": "section-044-09"
      }
